# Great! The transform/reverse works. But the encrypted test doesn't match
# the actual encrypted data from the binary.

# The encrypted test: 44c4c4cc8e4f0eae8f0d6f4dafec4a0f4f0ee96b89edae2e0d
# The actual at 0x3220: ada9191999b5a1bbb9a18795dddd87a1a7a7b18b39f303fbe93987058fa9bf

# This means the visible flag "kalmarctf{IcanREVthis???}" is NOT the correct input!
# The actual encrypted data corresponds to a different flag.

# Let me reverse the actual encrypted data
encrypted_actual = bytes([
    0xad, 0xa9, 0x19, 0x19, 0x99, 0xb5, 0xa1, 0xbb,
    0xb9, 0xa1, 0x87, 0x95, 0xdd, 0xdd, 0x87, 0xa1,
    0xa7, 0xa7, 0xb1, 0x8b, 0x39, 0xf3, 0x03, 0xfb,
    0xe9, 0x39, 0x87, 0x05, 0x8f, 0xa9, 0xbf
])

print(f"Encrypted length: {len(encrypted_actual)}")

# Try different lengths
for length in range(20, 32):
    try:
        decrypted = reverse_transform(encrypted_actual[:length])
        s = decrypted.decode('ascii', errors='strict')
        if all(32 <= ord(c) <= 126 for c in s):
            print(f"Length {length}: {repr(s)}")
    except:
        pass

# Also try with the null terminator
for length in range(20, 32):
    try:
        decrypted = reverse_transform(encrypted_actual[:length])
        s = decrypted.decode('latin-1')
        # Check if it starts with kalmarctf{ or similar
        if s.startswith('kalmar') or s.startswith('k') and 'ctf' in s:
            print(f"Length {length} (partial): {repr(s)}")
    except:
        pass

# Let me also check if the encrypted data might be the flag directly encrypted
# with a different key or method
print("\nTrying different XOR keys:")
for key in range(256):
    for length in [25, 26, 27, 28, 29, 30, 31]:
        try:
            # Just XOR without rotation
            xored = bytes([b ^ key for b in encrypted_actual[:length]])
            s = xored.decode('ascii')
            if s.startswith('kalmar'):
                print(f"Key {key}, Length {length}: {s}")
        except:
            pass
